class Unit:
    """Base class of the Jimple unit (statement) hierarchy.

    Units carry a deterministic, globally unique ``uid`` so that they can be
    used as dictionary/set keys without relying on object identity hashing.
    """

    _next_uid = 0

    __slots__ = (
        "uid",
        "stmt_id",
        "line_number",
        "source_stmt",
        "owner",
        "_succ_ids",
        "metadata",
    )

    def __init__(
        self,
        stmt_id: int = -1,
        line_number: int = 0,
        source_stmt: Statement | None = None,
    ) -> None:
        Unit._next_uid += 1
        self.uid = Unit._next_uid
        self.stmt_id = stmt_id
        self.line_number = line_number
        self.source_stmt = source_stmt
        self.owner: "SootMethod | None" = None
        self._succ_ids: list[int] = []
        self.metadata: dict[str, Any] = dict(source_stmt.metadata) if source_stmt else {}

    # -- classification ------------------------------------------------------
    def branches(self) -> bool:
        """True if control may transfer somewhere other than the next unit."""
        return False

    def falls_through(self) -> bool:
        """True if control may continue with the textually next unit."""
        return True

    def is_return(self) -> bool:
        return False

    # -- def/use -------------------------------------------------------------
    def get_def_boxes(self) -> list[Value]:
        return []

    def get_use_boxes(self) -> list[Value]:
        return []

    def get_defined_local(self) -> Local | None:
        for v in self.get_def_boxes():
            if isinstance(v, Local):
                return v
        return None

    def get_used_locals(self) -> list[Local]:
        out: list[Local] = []
        seen: set[str] = set()
        for v in self.get_use_boxes():
            for loc in v.used_locals():
                if loc.name not in seen:
                    seen.add(loc.name)
                    out.append(loc)
        return out

    # -- invoke helpers ------------------------------------------------------
    def contains_invoke_expr(self) -> bool:
        return self.get_invoke_expr() is not None

    def get_invoke_expr(self) -> InvokeExpr | None:
        return None

    def contains_field_ref(self) -> bool:
        return self.get_field_ref() is not None

    def get_field_ref(self) -> FieldRefValue | None:
        return None

    def contains_array_ref(self) -> bool:
        return self.get_array_ref() is not None

    def get_array_ref(self) -> ArrayRef | None:
        return None

    # -- taint metadata forwarded from the neutral program model -------------
    @property
    def is_source(self) -> bool:
        return bool(self.source_stmt.is_source) if self.source_stmt else False

    @property
    def is_sink(self) -> bool:
        return bool(self.source_stmt.is_sink) if self.source_stmt else False

    @property
    def source_category(self) -> str | None:
        return self.source_stmt.source_category if self.source_stmt else None

    @property
    def sink_category(self) -> str | None:
        return self.source_stmt.sink_category if self.source_stmt else None

    @property
    def kind(self) -> str:
        return self.source_stmt.kind if self.source_stmt else "nop"

    def get_java_source_start_line_number(self) -> int:
        return self.line_number

